int n , nq ; 
int a [maxn] ;
int T [maxn*4] ; 
void update ( int id , int l , int r, int pos , int w ) 
{
    if ( l > pos || r < pos ) return ; 
    if ( l == r ) 
    {
        T [id] += w ; 
        return ; 
    }
    update (left,l,mid,pos,w) , update (right,mid+1,r,pos,w) ; 
    T [id] = T [left] + T [right] ; 
}
int get ( int id , int l , int r , int u , int v ) 
{
    if ( l > v || r < u ) return 0 ; 
    if ( u <= l && r <= v ) return T [id] ; 
    return get (left,l,mid,u,v) + get (right,mid+1,r,u,v) ; 
}
signed main () 
{
    ios_base::sync_with_stdio(0); 
    cin.tie(0);cout.tie(0); 
    cin >> n >> nq ; 
    for ( int i = 1 ; i <= n ; i ++ ) cin >> a [i] , update (1,1,n,i,a[i]) ; 
    while ( nq -- ) 
    {
        int type ; cin >> type ; 
        if ( type == 1 ) 
        {
            int pos , w ; cin >> pos >> w ; 
            update (1,1,n,pos,w-a[pos]) ; a [pos] = w ;  
        }
        else 
        {
            int l,r ; cin >> l >> r ; 
            cout << get(1,1,n,l,r) << "\n" ; 
        }
    }
    return 0;
}
